window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-74aedf3df0b03def"]={"versions": [{"id": "FIG-74aedf3df0b03def", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation der Metamodell-Struktur für Berechnungs- und Umrechnungsvorschriften (<code>CompuMethod</code>) im Kontext des AUTOSAR Software Component Templates (TPS_SoftwareComponentTemplate). Es modelliert die semantische Definition einer Skala (<code>CompuScale</code>) und ihrer Ausprägungsformen als rationale Formel oder Festwert.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Klassen und Beziehungen:</p>\n<ul class=\"fig-list\"><li><strong><code>CompuScale</code></strong>: Zentrales Element mit Attributen <code>mask: PositiveInteger [0..1]</code>, <code>shortLabel: Identifier [0..1]</code> und <code>symbol: CIdentifier [0..1]</code>. Es besitzt eine Komposition <code>+compuInverseValue: CompuConst [0..1]</code> sowie eine Komposition <code>+compuScaleContents: CompuScaleContents [0..1]</code>.\n</li><li><strong><code>CompuScaleContents</code></strong>: Abstrakte Basisklasse (kursiv dargestellt) für den Inhalt einer Skala.\n</li><li><strong><code>CompuScaleRationalFormula</code></strong>: Spezialisierung von <code>CompuScaleContents</code>. Enthält per Komposition genau ein <code>+compuRationalCoeffs: CompuRationalCoeffs [1]</code>.\n</li><li><strong><code>CompuScaleConstantContents</code></strong>: Spezialisierung von <code>CompuScaleContents</code>. Enthält per Komposition genau ein <code>+compuConst: CompuConst [1]</code>.\n</li><li><strong><code>CompuRationalCoeffs</code></strong>: Enthält per Komposition jeweils genau ein <code>+compuNumerator: CompuNominatorDenominator [1]</code> und ein <code>+compuDenominator: CompuNominatorDenominator [1]</code>.\n</li><li><strong><code>CompuNominatorDenominator</code></strong>: Beinhaltet das variable Attribut <code>«atpVariation» + v: Numerical [0..*] {ordered}</code> zur Speicherung der Koeffizientenwerte.\n</li><li><strong><code>CompuConst</code></strong>: Repräsentiert konstante Werte für Inverswerte oder konstante Skaleninhalte.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell-Strukturdiagramm bildet die Darstellung keine Laufzeitsequenzen ab. Die Auswertung erfolgt deklarativ: Bei Skalenumrechnungen verzweigt die Auswertung über <code>CompuScaleContents</code> entweder in eine rationale gebrochen-rationale Funktion (<code>CompuScaleRationalFormula</code>) mit Zähler- und Nennerpolynomen (<code>CompuNominatorDenominator</code>) oder in die Zuordnung einer Konstanten (<code>CompuScaleConstantContents</code>). Zusätzlich kann über <code>compuInverseValue</code> ein Rückabbildungswert definiert sein.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Struktur erzwingt strikte Konsistenzbedingungen im Metamodell:</p>\n<ul class=\"fig-list\"><li>Ein Skaleninhalt (<code>CompuScaleContents</code>) ist polymorph ausgeprägt; pro Skala darf höchstens ein Skaleninhalt (<code>0..1</code>) deklariert werden.\n</li><li>Eine rationale Formel erfordert zwingend sowohl Zähler als auch Nenner als <code>CompuNominatorDenominator</code> (Multiplizität jeweils genau 1).\n</li><li>Die Koeffizientenliste <code>v</code> ist geordnet (<code>{ordered}</code>) und unterliegt dem AUTOSAR-Variabilitätskonzept (<code>«atpVariation»</code>), wodurch Polynomgrade und Koeffizienten über Bindungszeitpunkte variiert werden können.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-1c459616df188fe8", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation der Metamodell-Struktur für Berechnungs- und Umrechnungsvorschriften (<code>CompuMethod</code>) im Kontext des AUTOSAR Software Component Templates (TPS_SoftwareComponentTemplate). Es modelliert die semantische Definition einer Skala (<code>CompuScale</code>) und ihrer Ausprägungsformen als rationale Formel oder Festwert.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Klassen und Beziehungen:</p>\n<ul class=\"fig-list\"><li><strong><code>CompuScale</code></strong>: Zentrales Element mit Attributen <code>mask: PositiveInteger [0..1]</code>, <code>shortLabel: Identifier [0..1]</code> und <code>symbol: CIdentifier [0..1]</code> sowie den variablen Intervallgrenzen unter <code>«atpVariation»</code>: <code>lowerLimit: Limit [0..1]</code> und <code>upperLimit: Limit [0..1]</code>. Es besitzt eine Komposition <code>+compuInverseValue: CompuConst [0..1]</code> sowie eine Komposition <code>+compuScaleContents: CompuScaleContents [0..1]</code>.\n</li><li><strong><code>CompuScaleContents</code></strong>: Abstrakte Basisklasse (kursiv dargestellt) für den Inhalt einer Skala.\n</li><li><strong><code>CompuScaleRationalFormula</code></strong>: Spezialisierung von <code>CompuScaleContents</code>. Enthält per Komposition genau ein <code>+compuRationalCoeffs: CompuRationalCoeffs [1]</code>.\n</li><li><strong><code>CompuScaleConstantContents</code></strong>: Spezialisierung von <code>CompuScaleContents</code>. Enthält per Komposition genau ein <code>+compuConst: CompuConst [1]</code>.\n</li><li><strong><code>CompuRationalCoeffs</code></strong>: Enthält per Komposition jeweils genau ein <code>+compuNumerator: CompuNominatorDenominator [1]</code> und ein <code>+compuDenominator: CompuNominatorDenominator [1]</code>.\n</li><li><strong><code>CompuNominatorDenominator</code></strong>: Beinhaltet das variable Attribut <code>«atpVariation» + v: Numerical [0..*] {ordered}</code> zur Speicherung der Koeffizientenwerte.\n</li><li><strong><code>CompuConst</code></strong>: Repräsentiert konstante Werte für Inverswerte oder konstante Skaleninhalte.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell-Strukturdiagramm bildet die Darstellung keine Laufzeitsequenzen ab. Die Auswertung erfolgt deklarativ: Bei Skalenumrechnungen verzweigt die Auswertung über <code>CompuScaleContents</code> entweder in eine rationale gebrochen-rationale Funktion (<code>CompuScaleRationalFormula</code>) mit Zähler- und Nennerpolynomen (<code>CompuNominatorDenominator</code>) oder in die Zuordnung einer Konstanten (<code>CompuScaleConstantContents</code>). Zusätzlich kann über <code>compuInverseValue</code> ein Rückabbildungswert definiert sein.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Struktur erzwingt strikte Konsistenzbedingungen im Metamodell:</p>\n<ul class=\"fig-list\"><li>Ein Skaleninhalt (<code>CompuScaleContents</code>) ist polymorph ausgeprägt; pro Skala darf höchstens ein Skaleninhalt (<code>0..1</code>) deklariert werden.\n</li><li>Gültigkeitsbereiche für Skalen werden über <code>lowerLimit</code> und <code>upperLimit</code> eingegrenzt, welche varianzfähig (<code>«atpVariation»</code>) sind.\n</li><li>Eine rationale Formel erfordert zwingend sowohl Zähler als auch Nenner als <code>CompuNominatorDenominator</code> (Multiplizität jeweils genau 1).\n</li><li>Die Koeffizientenliste <code>v</code> ist geordnet (<code>{ordered}</code>) und unterliegt dem AUTOSAR-Variabilitätskonzept (<code>«atpVariation»</code>), wodurch Polynomgrade und Koeffizienten über Bindungszeitpunkte variiert werden können.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-74aedf3df0b03def", "to": "FIG-1c459616df188fe8", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Zu <code>CompuScale</code> wurden die variablen Attribute <code>lowerLimit: Limit [0..1]</code> und <code>upperLimit: Limit [0..1]</code> unter dem Stereotyp <code>«atpVariation»</code> hinzugefügt.\n</li><li>Die Komposition <code>+compuScaleContents</code> von <code>CompuScale</code> zu <code>CompuScaleContents</code> ist nicht mehr blau hervorgehoben, sondern als standardmäßige schwarze Kompositionslinie dargestellt.\n</li></ul>"}]};
